#!/usr/bin/env python3
"""Build a self-contained HTML viewer for a simple_games run directory."""
from __future__ import annotations
import argparse
import html
import json
from pathlib import Path


def load_jsonl(path: Path):
    if not path.exists():
        return [], []
    raw = path.read_bytes()
    lines = raw.splitlines(keepends=True)
    rows, notes = [], []
    for i, line in enumerate(lines, 1):
        if not line.endswith((b"\n", b"\r")):
            if i == len(lines):
                notes.append(f"{path.name}: ignored partial final line {i} while the file may still be growing.")
                continue
        if not line.strip():
            continue
        try:
            rows.append(json.loads(line))
        except (json.JSONDecodeError, UnicodeDecodeError) as exc:
            raise ValueError(f"{path.name}:{i}: malformed complete JSONL line: {exc}") from exc
    return rows, notes


def load_run(run_dir: Path, compact=False):
    manifest_path = run_dir / "manifest.json"
    manifest = json.loads(manifest_path.read_text()) if manifest_path.exists() else {}
    episodes, n1 = load_jsonl(run_dir / "episodes.jsonl")
    wire, n2 = load_jsonl(run_dir / "wire.jsonl")
    if compact:
        for event in wire:
            # Full exact requests remain in the immutable source wire logs.
            # Avoid embedding every growing conversation prefix a second time.
            event["request"] = {k: v for k, v in event.get("request", {}).items() if k != "messages"}
            event["request"]["prompt_omitted_from_compact_viewer"] = True
            response = event.get("response") or {}
            event["response"] = dict(response, choices=[{k: v for k, v in c.items() if k != "logprobs"}
                for c in response.get("choices", [])])
        n2.append("Compact viewer: full prompts and token logprobs remain in source wire.jsonl; transcripts, choices, generated IDs and usage are included here.")
    by_job = {}
    for call in wire:
        meta = call.get("metadata") or {}
        by_job.setdefault(meta.get("job_index"), []).append(call)
    for calls in by_job.values():
        calls.sort(key=lambda c: (c.get("call", 0),))
    data = []
    for episode in episodes:
        data.append({"episode": episode, "calls": by_job.get(episode.get("job_index"), [])})
    return {"manifest": manifest, "items": data, "notes": n1 + n2,
            "recorded_episode_count": len(episodes), "wire_count": len(wire)}


