def build(run_dir: Path, out: Path, compact=False):
    payload = json.dumps(load_run(run_dir, compact=compact), ensure_ascii=False, separators=(",", ":"))
    payload = payload.replace("</", "<\\/").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(PAGE.replace("__DATA__", payload), encoding="utf-8")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--run-dir", required=True, type=Path)
    parser.add_argument("--out", required=True, type=Path)
    parser.add_argument("--compact", action="store_true", help="Omit duplicated prompt prefixes and logprobs; retain complete transcripts and generated IDs")
    args = parser.parse_args()
    build(args.run_dir, args.out, compact=args.compact)
    print(f"Wrote {args.out}")

if __name__ == "__main__":
    main()
